mapper.select:
SELECT COUNT(*) FROM ( SELECT a.biz_type,b.lessee_type,@rank := @rank + 1 rank_number FROM (SELECT origin_id,biz_type,max(version) AS version FROM contract_base_info_lib cb GROUP BY origin_id) a
INNER JOIN (SELECT contract_id,lessee_id,version,is_report,lessee_type FROM contract_tenantry_lib ct WHERE lessee_type = 'MAIN_LESSSEE' OR lessee_type = 'CREDITOR') b INNER JOIN payment_base_info c INNER JOIN (SELECT @rank := 0) rank_number WHERE a.origin_id = b.contract_id AND a.version = b.version AND a.origin_id = c.contract_id AND b.is_report = 1 AND c.write_off_status = 'WRITTEN_OFF' AND b.lessee_id = #{clientId}
) d WHERE (((biz_type = 'ZL' OR biz_type = 'ZZ') AND lessee_type = 'MAIN_LESSSEE') OR (biz_type = 'BL' AND rank_number = 1))

SELECT COUNT(*) FROM ( SELECT a.biz_type,b.lessee_type,@rank := @rank + 1 rank_number FROM (SELECT origin_id,biz_type,max(version) AS version FROM contract_base_info_lib cb GROUP BY origin_id) a
INNER JOIN (SELECT contract_id,lessee_id,version,is_report,lessee_type FROM contract_tenantry_lib ct WHERE lessee_type = 'MAIN_LESSSEE' OR lessee_type = 'CREDITOR') b INNER JOIN payment_base_info c INNER JOIN (SELECT @rank := 0) rank_number WHERE a.origin_id = b.contract_id AND a.version = b.version AND a.origin_id = c.contract_id AND b.is_report = 1 AND c.write_off_status IN ('WRITTEN_OFF', 'PART_WRITTEN_OFF') AND b.lessee_id = #{clientId}
) d WHERE (((biz_type = 'ZL' OR biz_type = 'ZZ') AND lessee_type = 'MAIN_LESSSEE') OR (biz_type = 'BL' AND rank_number = 1))
